import json, os, sys
from pathlib import Path

limits = json.loads(os.environ['OCTOPUS_INTERFACE_HOST_IO_LIMITS'])
pending = {}

def send(frame):
    data = json.dumps(frame, separators=(',', ':')).encode() + b'\n'
    if len(data) > limits['max_control_frame_bytes']:
        raise ValueError('control frame exceeds declared limit')
    sys.stdout.buffer.write(data)
    sys.stdout.buffer.flush()

def read_json(path, limit):
    with open(path, 'rb') as source:
        data = source.read(limit + 1)
    if len(data) > limit:
        raise ValueError('artifact exceeds declared limit')
    return json.loads(data)

while True:
    line = sys.stdin.buffer.readline(limits['max_control_frame_bytes'] + 1)
    if not line:
        break
    if len(line) > limits['max_control_frame_bytes']:
        raise ValueError('input control frame exceeds declared limit')
    message = json.loads(line)
    request = message['request_id']
    try:
        if type(request) is not int or request < 0:
            raise ValueError('invalid request id')
        if message['kind'] == 'invoke':
            descriptor, envelope = message['descriptor'], message['envelope']
            formation, kind = envelope['worker_environment'], envelope['worker_environment_kind']
            if descriptor['interface'] != os.environ['OCTOPUS_INTERFACE_ID'] or formation['door_interface'] != descriptor['interface']:
                raise ValueError('wrong door')
            if descriptor['supported_worker_environment_kinds'] != [formation['worker_environment_kind']] or kind['worker_environment_kind_id'] != formation['worker_environment_kind']:
                raise ValueError('wrong owner kind')
            if descriptor['id'] not in formation['granted_tools'] or formation['requires_release']:
                raise ValueError('tool grant missing or this stateless example cannot own required release')
            manifest_path = Path(envelope['manifest_path'])
            manifest = read_json(manifest_path, limits['max_manifest_bytes'])
            if manifest['label'] != envelope['label'] or envelope['label'] != 'tool.call':
                raise ValueError('wrong input label')
            call = read_json(manifest_path.parent / manifest['payload_path'], limits['max_payload_bytes'])
            if call['tool'] != descriptor['id'] or set(call['arguments']) != {'value'} or not isinstance(call['arguments']['value'], str):
                raise ValueError('invalid echo arguments')
            if request in pending:
                raise ValueError('duplicate pending request')
            pending[request] = call
            send({'kind':'worker_environment_lifecycle','request_id':request,'event_id':1,'worker_environment_id':formation['worker_environment_id'],'lifecycle':'active'})
        elif message['kind'] == 'worker_environment_lifecycle_recorded':
            call = pending.pop(request)
            if message['event_id'] != 1 or message['error'] is not None:
                raise ValueError('lifecycle was not recorded: ' + str(message.get('error')))
            result = {'label':call['tool']+'.result','tool':call['tool'],'ok':True,'body':{'value':call['arguments']['value']}}
            if call.get('correlation_id') is not None:
                result['correlation_id'] = call['correlation_id']
            output = Path(os.environ['OCTOPUS_VAR_DIR']) / ('result-' + str(request))
            payload = json.dumps(result, separators=(',', ':')).encode()
            if len(payload) > limits['max_payload_bytes']:
                raise ValueError('result exceeds declared limit')
            output.write_bytes(payload)
            manifest_path = output.with_suffix('.json')
            manifest_path.write_text(json.dumps({'label':result['label'],'payload_path':str(output)}))
            send({'kind':'complete','request_id':request,'artifact_manifest_paths':[str(manifest_path)]})
        elif message['kind'] == 'release_worker_environment':
            if pending or message['formation']['requires_release']:
                raise ValueError('cannot acknowledge release of an owned resource')
            send({'kind':'worker_environment_released','request_id':request})
        else:
            raise ValueError('unexpected input frame: ' + message['kind'])
    except Exception as error:
        pending.pop(request, None)
        send({'kind':'failed','request_id':request,'error':str(error)})
